async addMessage(msgHdr) {
  if (this.isDone || !this.currentPage) {
    return;
  }

  // Skip messages, which are actually deleted, if reporting is not enforced.
  if (
    !this.includeDeletedMessages &&
    msgHdr.flags &
      (Ci.nsMsgMessageFlags.IMAPDeleted | Ci.nsMsgMessageFlags.Expunged)
  ) {
    return;
  }

  const messageHeader = this.extension.messageManager.convert(msgHdr, {
    skipFolder: true,
  });
  if (!messageHeader || this.log.has(messageHeader.id)) {
    return;
  }

onMoved({ fire }) {
  const listener = async (event, srcMessages, dstMessages) => {
    const { extension } = this;
    // The msgHdr could be gone after the wakeup, convert them early.
    const srcPage = await messageListTracker.startList(
      srcMessages,
      extension,
      { includeDeletedMessages: true }
    );
    const dstPage = await messageListTracker.startList(
      dstMessages,
      extension,
      { includeDeletedMessages: true }
    );
    if (fire.wakeup) {
      await fire.wakeup();
    }
    fire.async(srcPage, dstPage);

onDeleted({ fire }) {
  const listener = async (event, deletedMessages) => {
    const { extension } = this;
    // The msgHdr could be gone after the wakeup, convert them early.
    const deletedPage = await messageListTracker.startList(
      deletedMessages,
      extension,
      { includeDeletedMessages: true }
    );
    if (fire.wakeup) {
      await fire.wakeup();
    }
    fire.async(deletedPage);
